const item = $input.first().json;
const raw = item.text ?? item.output;

if (typeof raw !== 'string') {
  throw new Error('AI output not found: expected "text" or "output". Got keys: ' + Object.keys(item).join(', '));
}

const clean = raw.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
return [{ json: JSON.parse(clean) }];

const d = $input.first().json;
const year = s => (String(s).match(/\d{4}/) || [s])[0];

return [{ json: {
  titre: d.titre,
  annees_experience: d.annees_experience,
  competences: d.competences,
  experiences: d.experiences.map(e => ({
    secteur: e.secteur, poste: e.poste,
    debut: year(e.debut), fin: year(e.fin),
    missions: e.missions, environnement: e.environnement
  })),
  formations: d.formations.map(f => ({ diplome: f.diplome, annee: f.annee })),
  langues: d.langues,
  certifications: d.certifications
}}];

const item = $input.first().json;
const raw = item.text ?? item.output;

if (typeof raw !== 'string') {
  throw new Error('AI output not found: expected "text" or "output". Got keys: ' + Object.keys(item).join(', '));
}

const clean = raw.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
return [{ json: JSON.parse(clean) }];

const c = $input.first().json;
const AGENCY = 'Fil Rouge Consulting';

const esc = s => String(s ?? '').replace(/[&<>"']/g,
  m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const period = e => e.debut === e.fin ? e.debut : `${e.debut} – ${e.fin}`;

const html = `<!DOCTYPE html>
<html lang="fr"><head><meta charset="utf-8">
<style>
  @page { size: A4; margin: 0; }
  body { font-family: Arial, Helvetica, sans-serif; margin: 0; color: #1a2233; font-size: 12px; }
  header { background: #a3123a; color: #fff; padding: 28px 40px; display: flex; justify-content: space-between; }
  header .agency { font-size: 20px; font-weight: bold; }
  header .sub { font-size: 9px; letter-spacing: 2px; margin-top: 6px; }
  header .ref { text-align: right; }
  main { padding: 24px 40px; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  .years { color: #a3123a; font-weight: bold; margin-bottom: 14px; }
  h2 { color: #a3123a; font-size: 12px; letter-spacing: 1px; text-transform: uppercase;
       border-bottom: 1px solid #ddd; padding-bottom: 4px; margin: 18px 0 8px; }
  .summary { background: #fdeeee; border-left: 3px solid #a3123a; padding: 10px 14px; line-height: 1.5; }
  .tag { display: inline-block; border: 1px solid #c8d0dc; background: #eef2f8;
         border-radius: 12px; padding: 3px 10px; margin: 0 4px 4px 0; }
  .row { display: flex; justify-content: space-between; margin-top: 10px; }
  .muted { color: #666; }
  ul { margin: 4px 0; padding-left: 18px; }
  .env { font-size: 11px; }
  .cols { display: flex; gap: 40px; } .cols > div { flex: 1; }
  footer { text-align: center; font-size: 9px; color: #777; border-top: 1px solid #ddd;
           margin: 20px 40px 0; padding-top: 8px; }
</style></head><body>
<header>
  <div><div class="agency">${esc(AGENCY)}</div><div class="sub">DOSSIER DE COMPÉTENCES</div></div>
  <div class="ref"><div>Réf. consultant</div><div><b>${esc(c.code)}</b></div><div>${esc(c.date)}</div></div>
</header>
<main>
  <h1>${esc(c.titre)}</h1>
  <div class="years">${Math.floor(c.annees_experience)} ans d'expérience</div>

  <h2>Synthèse du profil</h2>
  <div class="summary">${esc(c.accroche)}</div>

  <h2>Compétences clés</h2>
  <div>${c.competences.map(s => `<span class="tag">${esc(s)}</span>`).join('')}</div>

  <h2>Expériences professionnelles</h2>
  ${c.experiences.map(e => `
    <div class="row"><div><b>${esc(e.poste)}</b> — <span class="muted">${esc(e.secteur)}</span></div>
      <div class="muted">${esc(period(e))}</div></div>
    <ul>${e.missions.map(m => `<li>${esc(m)}</li>`).join('')}</ul>
    <div class="env"><b>Environnement :</b> ${esc(e.environnement.join(', '))}</div>`).join('')}

  <h2>Formation</h2>
  ${c.formations.map(f => `<div><b>${esc(f.annee)}</b> — ${esc(f.diplome)} <span class="muted">(${esc(f.type)})</span></div>`).join('')}

  <div class="cols">
    <div><h2>Langues</h2><ul>${c.langues.map(l => `<li>${esc(l)}</li>`).join('')}</ul></div>
    <div><h2>Certifications</h2><ul>${c.certifications.map(x => `<li>${esc(x.nom)} — ${esc(x.annee)}</li>`).join('')}</ul></div>
  </div>
</main>
<footer>Document confidentiel — CV anonymisé conformément au RGPD — ${esc(AGENCY)} · Réf. ${esc(c.code)}</footer>
</body></html>`;

return [{ json: { ...c, html } }];

const full = $('Parse JSON').first().json;      // real data (never output)
const reduced = $('Prepare payload').first().json;
const ai = $('Parse AI2').first().json;

if (ai.missions.length !== reduced.experiences.length) {
  throw new Error('AI2 returned ' + ai.missions.length +
    ' mission groups, expected ' + reduced.experiences.length);
}

// Consultant code: CONS- + 6 characters (no ambiguous 0/O/1/I)
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const rand = Array.from({ length: 6 },
  () => chars[Math.floor(Math.random() * chars.length)]).join('');

// School name -> generic type
const schoolType = name => {
  if (/universit/i.test(name)) return 'Université';
  if (/lyc[ée]e/i.test(name)) return 'Lycée';
  if (/[ée]cole|institut|iut/i.test(name)) return 'École';
  return 'Établissement';
};

return [{ json: {
  code: 'CONS-' + rand,
  date: new Date().toLocaleDateString('fr-FR'),
  titre: reduced.titre,
  annees_experience: reduced.annees_experience,
  accroche: ai.accroche,
  competences: reduced.competences,
  experiences: reduced.experiences.map((e, i) => ({
    secteur: e.secteur, poste: e.poste,
    debut: e.debut, fin: e.fin,
    missions: ai.missions[i],
    environnement: e.environnement
  })),
  formations: full.formations.map(f => ({
    type: schoolType(f.ecole), diplome: f.diplome, annee: f.annee
  })),
  langues: reduced.langues,
  certifications: reduced.certifications
}}];

const full = $('Parse JSON').first().json;
const item = $input.first().json;

const norm = s => String(s ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const digits = s => String(s ?? '').replace(/\D/g, '');
const esc = s => String(s).replace(/[&<>"']/g,
  m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const visible = h => norm(h.replace(/<[^>]*>/g, ' ')
  .replace(/&#39;/g, "'").replace(/&amp;/g, '&'));

const secrets = [
  ['nom', full.nom], ['prenom', full.prenom], ['email', full.email],
  ['telephone', full.telephone], ['ville', full.ville], ['adresse', full.adresse],
  ...(full.liens || []).map((l, i) => ['lien ' + (i + 1), l]),
  ...full.experiences.map((e, i) => ['employeur ' + (i + 1), e.employeur]),
  ...full.formations.map((f, i) => ['ecole ' + (i + 1), f.ecole]),
].filter(([, v]) => norm(v).length >= 3);

const findLeaks = html => {
  const text = visible(html);
  return secrets.filter(([label, v]) => label === 'telephone'
    ? digits(text).includes(digits(v))
    : text.includes(norm(v)));
};

// 1. detect
const leaks = findLeaks(item.html);

// 2. redact
let html = item.html;
for (const [, v] of leaks) {
  for (const variant of [String(v), esc(v)]) {
    html = html.replace(new RegExp(escRe(variant), 'gi'), '[masqué]');
  }
}

// 3. verify: if anything survives, block
const remaining = findLeaks(html);
if (remaining.length) {
  throw new Error('RGPD: unfixable leak in: ' + remaining.map(([l]) => l).join(', '));
}

return [{ json: { ...item, html, alertes: leaks.length } }];

const item = $input.first();
const code = $('Assemble CV').first().json.code;

item.binary.pdf.fileName = `CV_anonymise_${code}.pdf`;
return [item];

const full = $('Parse JSON').first().json;
const cv = $('Assemble CV').first().json;
const form = $('Webhook').first();   // your form node's name

const row = {
  'Code consultant': cv.code,
  'Date de traitement': cv.date,
  'Prénom': full.prenom,
  'Nom': full.nom,
  'E-mail': full.email,
  'Téléphone': full.telephone,
  'Adresse': full.adresse ?? full.ville,
  'Liens (LinkedIn, GitHub…)': (full.liens || []).join(', '),
  'Poste': full.titre,
  "Années d'expérience": Math.floor(cv.annees_experience),
  'Compétences': (full.competences || []).join(', '),
  'Lien CV anonymisé': 'http://localhost:5678/webhook/cv-anonyme?code=' + cv.code,
  'Fichier source': form.binary.CV.fileName,
  'Alertes RGPD rattrapées': $('Leak check').first().json.alertes,
};

return [{ json: row }];

const code = $('Assemble CV').first().json.code;
return [{ json: {
  code,
  link: 'http://localhost:5678/webhook/cv-anonyme?code=' + code,
  alertes: $('Leak check').first().json.alertes
}}];
